import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.provider.Settings;import org.json.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;

final class Updates {
 final MainActivity activity;final File dir,apk,manifest;final SharedPreferences prefs;final ExecutorService owner=Executors.newSingleThreadExecutor(),pool=Executors.newFixedThreadPool(4);JSONObject state=new JSONObject(),payload;String envelope="";boolean busy=false,waitingPermission=false;volatile boolean cancelled=false;long revision;volatile HttpURLConnection activeDownload;
 Updates(MainActivity a){activity=a;dir=new File(a.getFilesDir(),"updates");dir.mkdirs();apk=new File(dir,"release.apk");manifest=new File(dir,"manifest.json");prefs=a.getSharedPreferences("updates20",0);set("phase","idle");set("message","更新检查使用镜像备用线路，不影响资料库操作。");owner.execute(()->{try{if(apk.isFile()&&manifest.isFile()){String raw=new String(java.nio.file.Files.readAllBytes(manifest.toPath()),java.nio.charset.StandardCharsets.UTF_8);JSONObject p=UpdateProtocol.verify(raw);if(UpdateProtocol.compare(p.getString("version"),UpdateProtocol.CURRENT)>0){UpdateProtocol.verifyFile(apk,p.getJSONObject("android"));synchronized(this){payload=p;envelope=raw;}change("ready","已校验的安装包可以安装。");}}}catch(Exception ignored){}});}
 synchronized void set(String k,Object v){try{state.put(k,v);}catch(JSONException ignored){}}
 synchronized String snapshot(){set("revision",++revision);set("current",UpdateProtocol.CURRENT);set("automatic",prefs.getBoolean("automatic",true));set("custom",prefs.getString("custom",""));set("preferred",prefs.getString("preferred",""));set("checkedAt",prefs.getLong("checkedAt",0));if(payload!=null){set("latest",payload.optString("version"));set("notes",payload.optString("notes"));}return state.toString();}
 void publish(){activity.updateState20(snapshot());}
 void change(String phase,String message){synchronized(this){set("phase",phase);set("message",message);}publish();}
 synchronized boolean begin(){if(busy)return false;busy=true;cancelled=false;return true;}
 synchronized void end(){busy=false;}
 List<String> routes(){LinkedHashSet<String> rows=new LinkedHashSet<>();String custom=prefs.getString("custom",""),preferred=prefs.getString("preferred","");if(!custom.isEmpty())rows.add(custom);if(!preferred.isEmpty())rows.add("direct".equals(preferred)?"":preferred);Collections.addAll(rows,UpdateProtocol.MIRRORS);return new ArrayList<>(rows);}
 synchronized String request(String json)throws Exception{JSONObject x=new JSONObject(json);String action=x.getString("action");switch(action){case "state":break;case "settings":String custom=UpdateProtocol.prefix(x.optString("custom")),preferred=x.optString("preferred");if(!preferred.isEmpty()&&!"direct".equals(preferred)&&!Arrays.asList(UpdateProtocol.MIRRORS).contains(preferred))throw new IOException("未知更新线路");prefs.edit().putBoolean("automatic",x.getBoolean("automatic")).putString("custom",custom).putString("preferred",preferred).apply();break;case "auto":check(true);break;case "check":check(false);break;case "download":download();break;case "cancel":cancelled=true;HttpURLConnection c=activeDownload;if(c!=null)c.disconnect();break;case "install":install();break;default:throw new IOException("未知更新操作");}return snapshot();}
 void check(boolean auto){if(auto&&(!prefs.getBoolean("automatic",true)||System.currentTimeMillis()/1000-prefs.getLong("checkedAt",0)<21600))return;final boolean wasReady="ready".equals(state.optString("phase"));if(!begin())return;change("checking","正在检查版本，镜像线路并行响应…");final List<String> routes=routes();owner.execute(()->{List<Future<String[]>> jobs=new ArrayList<>();try{CompletionService<String[]> done=new ExecutorCompletionService<>(pool);for(String route:routes)jobs.add(done.submit(()->{String raw=UpdateProtocol.read(route+UpdateProtocol.MANIFEST+"?t="+(System.currentTimeMillis()/3600000));UpdateProtocol.verify(raw);return new String[]{raw,route};}));JSONObject best=null;String raw="",route="";for(int n=0;n<jobs.size();n++){if(cancelled)throw new InterruptedIOException();try{String[] row=done.take().get();JSONObject p=UpdateProtocol.verify(row[0]);if(best==null||UpdateProtocol.compare(p.getString("version"),best.getString("version"))>0){best=p;raw=row[0];route=row[1];}}catch(ExecutionException ignored){}}if(cancelled)throw new InterruptedIOException();if(best==null)throw new IOException("所有更新线路暂时不可达，或签名校验失败。可稍后重试或更换镜像。");String v=best.getString("version");if(UpdateProtocol.compare(v,prefs.getString("highest",UpdateProtocol.CURRENT))<0)throw new IOException("线路返回旧版本信息，已阻止回退，请换线路重试。");synchronized(this){payload=best;envelope=raw;set("route",route.isEmpty()?"GitHub 直连":new URI(route).getHost());}prefs.edit().putString("highest",v).putLong("checkedAt",System.currentTimeMillis()/1000).apply();boolean newer=UpdateProtocol.compare(v,UpdateProtocol.CURRENT)>0;boolean cached=false;if(newer&&apk.isFile())try{UpdateProtocol.verifyFile(apk,best.getJSONObject("android"));java.nio.file.Files.write(manifest.toPath(),raw.getBytes(java.nio.charset.StandardCharsets.UTF_8));cached=true;}catch(Exception ignored){}change(cached?"ready":newer?"available":"latest",cached?"安装包已下载并校验，可确认安装。":newer?"发现新版本，下载后由你确认安装。":"当前已是最新版本。");}catch(Exception e){change(wasReady?"ready":cancelled?"idle":"error",cancelled?"已取消检查。":e.getMessage());}finally{for(Future<?> job:jobs)job.cancel(true);end();}});}
 void download()throws Exception{if(payload==null||UpdateProtocol.compare(payload.getString("version"),UpdateProtocol.CURRENT)<=0)throw new IOException("请先检查新版本");if("ready".equals(state.optString("phase"))||!begin())return;final JSONObject asset=payload.getJSONObject("android");final String raw=envelope;change("downloading","正在准备镜像下载…");owner.execute(()->{File part=new File(dir,"release.apk.part");try{long size=asset.getLong("size");Exception last=null;for(String route:routes()){if(cancelled)throw new InterruptedIOException();try{String name=route.isEmpty()?"GitHub 直连":new URI(route).getHost();set("route",name);set("received",0);set("total",size);change("downloading","正在从 "+name+" 下载；失败将自动换线。");HttpURLConnection c=UpdateProtocol.open(route+asset.getString("url"));activeDownload=c;try{long length=c.getContentLengthLong();if(length>0&&length!=size)throw new IOException("线路返回的安装包大小不正确");try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(part)){byte[] b=new byte[65536];long total=0,start=SystemClock.elapsedRealtime(),lastAt=start-500;for(int n;(n=in.read(b))!=-1;){if(cancelled)throw new InterruptedIOException();total+=n;if(total>size)throw new IOException("安装包超过声明大小");out.write(b,0,n);long now=SystemClock.elapsedRealtime();if(now-lastAt>=250||total==size){set("received",total);set("speed",total*1000/Math.max(1,now-start));publish();lastAt=now;}}if(cancelled)throw new InterruptedIOException();if(total!=size)throw new IOException("安装包下载中断");}}finally{c.disconnect();activeDownload=null;}UpdateProtocol.verifyFile(part,asset);validateApk(part,asset);java.nio.file.Files.move(part.toPath(),apk.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);java.nio.file.Files.write(manifest.toPath(),raw.getBytes(java.nio.charset.StandardCharsets.UTF_8));change("ready","下载完成，发布签名、文件与 APK 签名校验均已通过。");return;}catch(Exception e){last=e;part.delete();}}throw new IOException("下载线路均未成功，请重试或更换镜像。"+(last==null?"":" "+last.getMessage()));}catch(Exception e){part.delete();change(cancelled?"available":"error",cancelled?"已取消下载，可重新下载。":e.getMessage());}finally{end();}});}
 @SuppressWarnings("deprecation") void validateApk(File file,JSONObject asset)throws Exception{PackageManager pm=activity.getPackageManager();int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo candidate=pm.getPackageArchiveInfo(file.getAbsolutePath(),flags),installed=pm.getPackageInfo(activity.getPackageName(),flags);if(candidate==null||!activity.getPackageName().equals(candidate.packageName))throw new IOException("APK 不属于星匣");long next=Build.VERSION.SDK_INT>=28?candidate.getLongVersionCode():candidate.versionCode,current=Build.VERSION.SDK_INT>=28?installed.getLongVersionCode():installed.versionCode;if(next!=asset.getLong("versionCode")||next<=current)throw new IOException("APK 版本不匹配或属于旧版本");android.content.pm.Signature[] x=Build.VERSION.SDK_INT>=28?candidate.signingInfo.getApkContentsSigners():candidate.signatures,y=Build.VERSION.SDK_INT>=28?installed.signingInfo.getApkContentsSigners():installed.signatures;if(x==null||y==null||x.length!=y.length)throw new IOException("APK 发布签名与已安装应用不同");for(int i=0;i<x.length;i++)if(!x[i].equals(y[i]))throw new IOException("APK 发布签名与已安装应用不同");}
 void install()throws Exception{if(busy||!"ready".equals(state.optString("phase")))throw new IOException("请先完成下载并校验");if(!begin())return;change("installing","正在再次校验安装包…");owner.execute(()->{try{JSONObject p=UpdateProtocol.verify(envelope);UpdateProtocol.verifyFile(apk,p.getJSONObject("android"));validateApk(apk,p.getJSONObject("android"));activity.runOnUiThread(()->{end();if(Build.VERSION.SDK_INT>=26&&!activity.getPackageManager().canRequestPackageInstalls()){waitingPermission=true;change("ready","请允许星匣安装更新，返回后将打开系统安装确认。");try{activity.startActivityForResult(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())),74);}catch(Exception e){waitingPermission=false;change("ready","请在系统设置中允许星匣安装应用，再点击安装。");}}else openInstaller();});}catch(Exception e){end();change("error",e.getMessage());}});}
 void permissionResult(){if(!waitingPermission)return;waitingPermission=false;if(Build.VERSION.SDK_INT>=26&&activity.getPackageManager().canRequestPackageInstalls())try{install();}catch(Exception e){change("error",e.getMessage());}else change("ready","尚未允许安装。可稍后重新点击安装，已下载文件保留。");}
 void openInstaller(){try{Uri uri=Uri.parse("content://com.starcase.archive.updates/release.apk");Intent intent=new Intent(Intent.ACTION_VIEW);intent.setDataAndType(uri,"application/vnd.android.package-archive");intent.setClipData(ClipData.newRawUri("星匣更新",uri));intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);activity.startActivity(intent);change("ready","系统安装窗口已打开。点击“更新”完成安装；取消后可再次安装。");}catch(Exception e){change("ready","无法打开系统安装窗口："+e.getMessage());}}
}
